const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',calendar:'M4 5h16v16H4z M8 3v4 M16 3v4 M4 10h16 M8 14h2 M14 14h2 M8 17h2',people:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M16 4a4 4 0 0 1 0 8 M22 21v-2a4 4 0 0 0-3-3.87 M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',trophy:'M8 3h8v6a4 4 0 0 1-8 0z M8 5H4v2a4 4 0 0 0 4 4 M16 5h4v2a4 4 0 0 1-4 4 M12 13v6 M8 21h8 M10 19h4',wallet:'M3 5h16v15H3z M3 5l13-3v3 M15 11h6v5h-6z M17 13.5h1',plus:'M12 5v14 M5 12h14',chevron:'M9 5l7 7-7 7',left:'M15 5l-7 7 7 7',clock:'M12 8v4l3 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',pin:'M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0 M15 10a3 3 0 1 1-6 0 3 3 0 0 1 6 0',check:'M5 12l4 4L19 6',close:'M6 6l12 12 M6 18L18 6',arrow:'M5 12h14 M13 6l6 6-6 6',info:'M12 11v6 M12 7h.01 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',reset:'M3 11a9 9 0 1 1 2 7 M3 4v7h7',download:'M12 3v12 M7 10l5 5 5-5 M4 16v5h16v-5',shield:'M12 2l8 4v6c0 5-8 10-8 10S4 17 4 12V6z M8 11l3 3 5-6',mail:'M3 5h18v14H3z M3 5l9 7 9-7'};
paths.moon='M20.5 13a8.5 8.5 0 0 1-9.5-9.5A8.5 8.5 0 1 0 20.5 13';
paths.bell='M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9 M10 21h4';
paths.edit='M4 20l4-1 12-12-3-3L5 16z M14 7l3 3';
paths.trash='M3 6h18 M8 6V3h8v3 M5 6l1 15h12l1-15 M10 10v7 M14 10v7';
paths.restore='M3 11a9 9 0 1 1 2 7 M3 4v7h7 M12 7v5l3 2';
paths.match='M5 21V3 M5 4h13l-3 5 3 5H5';
const icon=k=>`<svg aria-hidden="true" viewBox="0 0 24 24"><path d="${paths[k]||paths.grid}"/></svg>`;
const initials=n=>n.split(' ').slice(0,2).map(s=>s[0]).join('');
const localDate=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const parseDate=s=>new Date(s+'T12:00:00');
const addDays=(s,n)=>{const d=parseDate(s);d.setDate(d.getDate()+n);return localDate(d)};
const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'America/Costa_Rica',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const monday=d=>addDays(d,-((parseDate(d).getDay()+6)%7));
const dateLabel=(s,opts={day:'numeric',month:'short'})=>parseDate(s).toLocaleDateString('es-CR',opts);
const weekLabel=s=>`${dateLabel(s,{day:'numeric'})}–${dateLabel(addDays(s,6),{day:'numeric',month:'long',year:'numeric'})}`;
const statuses={pending:['Pendiente','amber'],accepted:['Confirmado','green'],rejected:['Rechazado','red'],empty:['Sin asignar','gray']};
const badge=(text,color)=>`<span class="badge ${color}">${esc(text)}</span>`;
const statusBadge=s=>badge(...(statuses[s]||statuses.empty));
const uid=()=>crypto.randomUUID();
const KEY='arbitra-beta-v1';let storageOK=true;
function seedCalendarEvents(){return [{id:'demo-coordination',title:'Reunión de coordinación',category:'Reunión',date:addDays(today(),1),time:'18:00',duration:60,venue:'Sala de reuniones · demostración',notes:'Revisar la disponibilidad y la programación de la próxima jornada.',reminderDays:2,reminderSeen:false,status:'scheduled',sequence:0}]}
function seed(){
 const week=monday(today());
 const names=['Andrés Solís','Daniel Vargas','María Rodríguez','José Alvarado','Luis Chaves','Valeria Rojas','Carlos Méndez','Sofía Quesada'];
 const refs=names.map((name,i)=>({id:'r'+i,name,email:`${name.split(' ')[0].toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'')}@ejemplo.invalid`,level:i<4?'Primera categoría':'Segunda categoría',availability:Object.fromEntries(Array.from({length:7},(_,j)=>[addDays(week,j),{start:'06:00',end:'22:00'}]))}));
 refs[3].availability[addDays(week,5)]={start:'14:00',end:'22:00'};
 refs[6].availability[addDays(week,6)]={start:'06:00',end:'12:00'};
 const tournaments=[{id:'t1',name:'Copa Horizonte',organizer:'Comité deportivo local',category:'Fútbol 11 · Libre',refs:refs.map(r=>r.id)},{id:'t2',name:'Torneo Empresarial',organizer:'Organización empresarial',category:'Fútbol 7 · Libre',refs:refs.slice(0,6).map(r=>r.id)},{id:'t3',name:'Liga Juvenil Regional',organizer:'Comité de liga juvenil',category:'Fútbol 11 · Juvenil',refs:refs.slice(2).map(r=>r.id)}];
 const slot=(role,ref='',status='empty',fee=18000)=>({id:uid(),role,ref,status,fee,paid:false});
 const matches=[
 {id:'m1',tournament:'t1',home:'Deportivo Aurora',away:'Atlético Eclipse',date:addDays(week,5),time:'09:00',duration:120,venue:'Estadio Aurora · ubicación ficticia',lat:null,lng:null,charge:70000,collected:false,slots:[slot('Central','r0','pending',22000),slot('Asistente 1','r1','accepted',16000),slot('Asistente 2')]},
 {id:'m2',tournament:'t1',home:'Unión Cedros',away:'Sporting Cometa',date:addDays(week,5),time:'14:00',duration:120,venue:'Parque Deportivo Cedros · ubicación ficticia',lat:null,lng:null,charge:65000,collected:false,slots:[slot('Central','r2','accepted',22000),slot('Asistente 1','r3','accepted',16000),slot('Asistente 2','r4','accepted',16000)]},
 {id:'m3',tournament:'t2',home:'Titanes FC',away:'Deportivo Prisma',date:addDays(week,5),time:'16:00',duration:80,venue:'Complejo Prisma · ubicación ficticia',lat:null,lng:null,charge:35000,collected:true,slots:[slot('Central','r5','accepted',22000)]},
 {id:'m4',tournament:'t1',home:'Atlético Olivos',away:'Unión Estelar',date:addDays(week,6),time:'10:00',duration:120,venue:'Cancha Estelar · ubicación ficticia',lat:null,lng:null,charge:65000,collected:false,slots:[slot('Central'),slot('Asistente 1'),slot('Asistente 2')]},
 {id:'m5',tournament:'t3',home:'Academia Fénix',away:'Juvenil Centella',date:addDays(week,6),time:'14:00',duration:100,venue:'Estadio Centella · ubicación ficticia',lat:null,lng:null,charge:55000,collected:false,slots:[slot('Central','r2','pending',20000),slot('Asistente 1','r7','accepted',14000),slot('Asistente 2')]},
 {id:'m6',tournament:'t2',home:'Deportivo Atlas',away:'Halcones FC',date:addDays(week,4),time:'19:00',duration:80,venue:'Cancha Cometa · ubicación ficticia',lat:null,lng:null,charge:35000,collected:false,slots:[slot('Central','r0','accepted',22000)]}
 ];
 return {version:1,week,refs,tournaments,matches,calendarEvents:seedCalendarEvents(),events:[{text:'Beta lista para recorrer la primera jornada.',at:Date.now()}]};
}
let db;try{db=JSON.parse(localStorage.getItem(KEY));if(!db||db.version!==1||!Array.isArray(db.matches)||!Array.isArray(db.refs)||!Array.isArray(db.tournaments))db=seed()}catch{db=seed();storageOK=false}
migrateDemoLabels(db);
if(!Array.isArray(db.calendarEvents))db.calendarEvents=seedCalendarEvents();
let refPaymentState='all';
let matchPeriod='all',matchTournament='all',refScope='all',financeState='all',refTab='all';
let calendarMonth=today().slice(0,7),calendarDate=today(),calendarType='all';
let role='admin',view='overview',refId='r0',week=monday(today()),day='',filter='all',query='',financeTab='charges',tournamentFilter='all';
function persist(){try{localStorage.setItem(KEY,JSON.stringify(db));return true}catch{storageOK=false;toast('El navegador no permitió guardar. Los cambios durarán mientras esté abierta esta página.');return false}}
const reportUI=createReportUI({getDB:()=>db,getProfile:()=>({role,refId}),escapeHTML:esc,openModal,persist,render,toast,icon});
function log(text){db.events.unshift({text,at:Date.now()});db.events=db.events.slice(0,30);persist()}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4000)}
function tournament(m){return db.tournaments.find(t=>t.id===m.tournament)}
function refName(id){return db.refs.find(r=>r.id===id)?.name||'Sin asignar'}
const matchState=m=>m.slots.every(s=>s.status==='accepted')?'accepted':m.slots.some(s=>s.status==='pending')?'pending':'empty';
const sorted=ms=>[...ms].sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time));
const weekMatches=()=>sorted(liveMatches(db).filter(m=>m.date>=week&&m.date<=addDays(week,6)));
const navs={admin:[['overview','grid','Resumen'],['matches','match','Partidos'],['calendar','calendar','Calendario'],['reports','edit','Informes'],['tournaments','trophy','Torneos'],['refs','people','Árbitros'],['finance','wallet','Cobros y pagos']],ref:[['home','grid','Mis nombramientos'],['reports','edit','Mis informes'],['availability','calendar','Mi disponibilidad'],['history','wallet','Mis pagos']]};
const navTitle=()=>({trash:'Partidos eliminados',crews:'Equipos arbitrales listos',invitations:'Invitaciones pendientes',reminders:'Recordatorios'}[view]||navs[role].find(n=>n[0]===view)?.[2]||'Resumen');
const navActive=id=>view===id||(id==='matches'&&['crews','invitations','trash'].includes(view))||(id==='calendar'&&view==='reminders');
const weekButtons=()=>`<div class="week-controls"><button class="iconbtn" data-action="week-prev" aria-label="Semana anterior">${icon('left')}</button><span class="subtle">${weekLabel(week)}</span><button class="iconbtn" data-action="week-next" aria-label="Semana siguiente">${icon('chevron')}</button><button class="text-button" data-action="week-today">Esta semana</button></div>`;
function render(){
 const pending=liveMatches(db).flatMap(m=>m.slots).filter(s=>s.status==='pending').length;
 $('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand" aria-label="A"><span class="brand-mark">A</span></div><div class="workspace"><span class="avatar">AH</span><div style="font-size:11px">Asociación Horizonte<small>Espacio de demostración</small></div></div><div class="navlabel">${role==='admin'?'ADMINISTRACIÓN':'PORTAL DEL ÁRBITRO'}</div><nav class="nav ${role==='ref'?'ref-nav':''}" aria-label="Principal">${navs[role].map(([id,ico,label])=>`<button data-view="${id}" title="${label}" class="${navActive(id)?'active':''}" ${navActive(id)?'aria-current="page"':''}>${icon(ico)}${label}${id==='matches'&&pending?`<span class="count">${pending}</span>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="beta-box"><strong>Un espacio para probar</strong>Datos ficticios. Cambie de perfil para recorrer ambos lados del nombramiento.</div><button data-action="reset">${icon('reset')}Restablecer demostración</button></div></aside><main class="main" id="main-content" tabindex="-1"><header class="topbar"><div class="breadcrumb"><span class="breadcrumb-workspace">Asociación Horizonte</span><b>${navTitle()}</b></div><div class="top-right"><span class="demo-tag">BETA 1.5</span><button type="button" class="theme-toggle" data-action="toggle-theme" aria-label="Modo oscuro" aria-pressed="${window.ATheme.get()==='dark'}" title="Activar o desactivar modo oscuro">${icon('moon')}<span>Modo oscuro</span></button>${role==='admin'?`<button class="reminder-toggle" data-action="open-reminders" aria-label="Ver recordatorios">${icon('bell')}${dueReminders(db.calendarEvents).length?`<span>${dueReminders(db.calendarEvents).length}</span>`:''}</button>`:''}<label class="role-switch"><span class="role-label">Perfil de prueba</span><select id="role" aria-label="Cambiar perfil de demostración"><option value="admin" ${role==='admin'?'selected':''}>Administrador</option>${db.refs.map(r=>`<option value="${r.id}" ${role==='ref'&&refId===r.id?'selected':''}>Árbitro · ${esc(r.name)}</option>`).join('')}</select></label><div class="avatar">${role==='admin'?'AD':initials(refName(refId))}</div></div></header><div class="content">${content()}</div></main></div>`;
}
function head(eyebrow,title,subtitle,button=''){return `<div class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${subtitle}</p></div>${button}</div>`}
function stat(label,value,note,ico,action='') {
 const tag=action?'button':'div';
 return `<${tag} class="stat ${action?'stat-link':''}" ${action?`data-action="${action}"`:''}><div class="stat-top">${label}<span class="stat-icon">${icon(ico)}</span></div><strong>${value}</strong><small>${note}</small>${action?'<span class="stat-link-label">Ver detalle</span>':''}</${tag}>`;
}
function content(){
 if(view==='reports')return reportUI.page();
 if(role==='ref'){if(view==='availability')return availabilityPage();if(view==='history')return refHistory();return refereeHome()}
 if(view==='trash')return deletedMatchesPage();if(view==='tournaments')return tournamentsPage();if(view==='refs')return refsPage();if(view==='finance')return financePage();if(view==='calendar')return calendarPage();if(view==='reminders')return remindersPage();if(view==='crews')return crewsPage();if(view==='invitations')return invitationsPage();if(view==='matches')return matchesPage();return overview();
}
function overview(){
 const matches=weekMatches(),confirmed=matches.filter(m=>matchState(m)==='accepted').length,pending=matches.flatMap(m=>m.slots).filter(s=>s.status==='pending').length,empty=matches.flatMap(m=>m.slots).filter(s=>!active(s)).length;
 const available=db.refs.filter(r=>Object.keys(r.availability).some(d=>d>=week&&d<=addDays(week,6))).length;
 return head('ADMINISTRACIÓN','Resumen de la asociación',`${weekLabel(week)} · Consulte la jornada y sus pendientes.`,`<button class="btn primary" data-action="new-match">${icon('plus')}Nuevo partido</button>`)+
 `<div class="stats">${stat('Partidos esta semana',matches.length,`${db.tournaments.length} torneos registrados`,'calendar','summary-matches')}${stat('Equipos arbitrales listos',confirmed,`${confirmed} de ${matches.length} partidos`,'check','summary-crews')}${stat('Invitaciones pendientes',pending,`${empty} puestos por cubrir`,'mail','summary-invitations')}${stat('Árbitros con disponibilidad',available,`De ${db.refs.length} integrantes`,'people','summary-refs')}</div>${reminderBanner()}<div class="grid-main"><section class="panel"><div class="panel-header"><div><h2>Partidos de esta semana</h2><p>${weekLabel(week)} · ${matches.length} partidos</p></div><button class="text-button" data-view="matches">Ver todos los partidos</button></div>${matches.length?matches.slice(0,3).map(matchCard).join(''):emptyState('No hay partidos esta semana.','Puede registrar un partido o consultar la programación de otras fechas.')+`<div class="empty-actions"><button class="btn secondary" data-view="matches">Ver todos los partidos</button></div>`}<div class="panel-footer"><button class="btn secondary small" data-view="calendar">${icon('calendar')}Abrir calendario</button></div></section>${sidePanel(empty)}</div><section class="quick-links" aria-label="Accesos rápidos">${[['calendar','calendar','Calendario','Partidos, eventos y recordatorios'],['tournaments','trophy','Torneos','Competiciones y paneles arbitrales'],['refs','people','Árbitros','Integrantes y disponibilidad'],['finance','wallet','Cobros y pagos','Cuentas de la asociación']].map(([v,i,t,n])=>`<button data-view="${v}" class="quick-link">${icon(i)}<span><strong>${t}</strong><small>${n}</small></span></button>`).join('')}</section><p class="privacy-note">Beta 1.5 · Datos ficticios guardados en este navegador. Los perfiles se simulan y no se envían correos.</p>`;
}
function periodSelect(){return `<label class="compact-label">Periodo<select id="match-period" aria-label="Periodo"><option value="all" ${matchPeriod==='all'?'selected':''}>Todos los partidos</option><option value="week" ${matchPeriod==='week'?'selected':''}>Esta semana</option></select></label>`}
function matchBase(){return sorted(liveMatches(db).filter(m=>(matchPeriod==='all'||(m.date>=week&&m.date<=addDays(week,6)))&&(matchTournament==='all'||m.tournament===matchTournament)))}
function matchesPage(){return head('PROGRAMACIÓN','Partidos','Consulte y gestione cada partido y su equipo arbitral.',`<div class="actions"><button class="btn secondary" data-action="show-deleted-matches">${icon('trash')}Eliminados (${db.matches.filter(m=>m.deletedAt).length})</button><button class="btn primary" data-action="new-match">${icon('plus')}Nuevo partido</button></div>`)+`<div class="toolbar">${periodSelect()}<label class="compact-label">Torneo<select id="match-tournament" aria-label="Torneo de los partidos"><option value="all">Todos los torneos</option>${db.tournaments.map(t=>`<option value="${t.id}" ${matchTournament===t.id?'selected':''}>${esc(t.name)}</option>`).join('')}</select></label><button class="btn secondary small" data-view="calendar">${icon('calendar')}Ver calendario</button></div><section class="panel"><div class="panel-header"><div><h2>Lista de partidos</h2><p>${matchPeriod==='week'?weekLabel(week):'Todas las fechas'} · ${matchBase().length} partidos antes de filtrar por estado</p></div></div><div class="filterbar"><button class="chip ${filter==='all'?'active':''}" data-filter="all">Todos</button><button class="chip ${filter==='empty'?'active':''}" data-filter="empty">Por completar</button><button class="chip ${filter==='pending'?'active':''}" data-filter="pending">Esperando respuesta</button><button class="chip ${filter==='accepted'?'active':''}" data-filter="accepted">Equipos completos</button><span class="spacer"></span><input class="search" id="search" placeholder="Buscar equipo o torneo" aria-label="Buscar equipo o torneo" value="${esc(query)}"></div><div id="match-list">${matchList()}</div></section>`}
function matchList(){const items=matchBase().filter(m=>(!day||m.date===day)&&(filter==='all'||(filter==='empty'?matchState(m)!=='accepted':matchState(m)===filter))&&`${m.home} ${m.away} ${tournament(m)?.name}`.toLocaleLowerCase().includes(query.toLocaleLowerCase()));return items.length?items.map(matchCard).join(''):emptyState('No hay partidos con estos filtros.','Cambie el periodo o agregue un nuevo partido.','calendar')}
function matchCard(m) {
 const names=m.slots.filter(s=>s.status==='accepted').map(s=>refName(s.ref));
 return `<article class="match"><div class="match-top"><span class="tournament-tag">${esc(tournament(m)?.name)}</span>${badge(matchState(m)==='accepted'?'Equipo completo':matchState(m)==='pending'?'Esperando respuesta':'Por completar',statuses[matchState(m)][1])}</div><div class="teams"><span class="team-name">${esc(m.home)}</span><span class="versus">vs</span><span class="team-name">${esc(m.away)}</span></div><div class="match-meta"><span>${icon('calendar')}${dateLabel(m.date,{weekday:'short',day:'numeric',month:'short'})}</span><span>${icon('clock')}${esc(m.time)}–${endTime(m.time,m.duration)}</span><span>${icon('pin')}${esc(m.venue)}</span></div><div class="match-bottom"><div class="crew">${names.slice(0,3).map(n=>`<span class="avatar" title="${esc(n)}">${esc(initials(n))}</span>`).join('')}<small>${names.length} de ${m.slots.length} confirmados</small></div><button class="btn ${matchState(m)==='accepted'?'secondary':'primary'} small" data-action="assign" data-id="${m.id}">${matchState(m)==='accepted'?'Ver equipo arbitral':'Asignar árbitros'}</button></div>${role==='admin'?`<div class="match-management">${reportUI.button(m)}<button class="btn secondary small" data-action="edit-match" data-id="${m.id}">${icon('edit')}Editar partido</button><details class="match-more"><summary>Más opciones</summary><div class="match-more-actions"><button class="btn secondary small" data-action="reschedule-match" data-id="${m.id}">${icon('clock')}Reprogramar</button><button class="btn danger small" data-action="delete-match" data-id="${m.id}">${icon('trash')}Eliminar partido</button></div></details></div>`:''}</article>`;
}
function crewsPage(){const matches=matchBase().filter(m=>matchState(m)==='accepted');return head('NOMBRAMIENTOS CONFIRMADOS','Equipos arbitrales listos','Vea quién integra el equipo arbitral de cada partido.',`<button class="btn secondary" data-view="matches">Ver partidos</button>`)+`<div class="toolbar">${periodSelect()}<span class="subtle">${matches.length} equipos completos ${matchPeriod==='week'?'· '+weekLabel(week):''}</span></div><div class="crew-grid">${matches.length?matches.map(m=>`<section class="panel">${matchCard(m)}<div class="crew-details">${m.slots.map(s=>`<div class="person"><span class="avatar">${esc(initials(refName(s.ref)))}</span><div><strong>${esc(refName(s.ref))}</strong><small>${esc(s.role)} · ${money(s.fee)}</small></div>${statusBadge(s.status)}</div>`).join('')}</div></section>`).join(''):emptyState('Todavía no hay equipos arbitrales completos.','Se muestran cuando todos los puestos han sido aceptados.','people')}</div>`}
function invitationsPage(){const invitations=matchBase().flatMap(m=>m.slots.filter(s=>s.status==='pending').map(s=>({m,s})));return head('RESPUESTAS PENDIENTES','Invitaciones pendientes','Cada fila corresponde a una invitación que espera respuesta.',`<button class="btn secondary" data-view="matches">Ver partidos</button>`)+`<div class="toolbar">${periodSelect()}<span class="subtle">${invitations.length} invitaciones ${matchPeriod==='week'?'· '+weekLabel(week):''}</span></div><section class="panel"><div class="table-wrap"><table><thead><tr><th>Árbitro / puesto</th><th>Partido / fecha</th><th>Honorarios</th><th>Acciones</th></tr></thead><tbody>${invitations.map(({m,s})=>`<tr><td><strong>${esc(refName(s.ref))}</strong><small>${esc(s.role)}</small></td><td>${esc(m.home)} vs ${esc(m.away)}<small>${dateLabel(m.date)} · ${esc(m.time)} · ${esc(tournament(m)?.name)}</small></td><td>${money(s.fee)}</td><td><div class="actions"><button class="btn secondary small" data-action="assign" data-id="${m.id}">Revisar</button><button class="text-button" data-action="as-ref" data-id="${s.ref}">Probar respuesta</button></div></td></tr>`).join('')||'<tr><td colspan="4">No hay invitaciones pendientes en este periodo.</td></tr>'}</tbody></table></div></section>`}
function calendarPage(){const days=monthDays(calendarMonth),monthText=dateLabel(calendarMonth+'-01',{month:'long',year:'numeric'}),monthItems=days.filter(d=>d.startsWith(calendarMonth)).flatMap(d=>agendaItems(db,d,calendarType));return head('AGENDA DE LA ASOCIACIÓN','Calendario','Todos los partidos y sus eventos, organizados por fecha.',`<button class="btn primary" data-action="new-event">${icon('plus')}Nuevo evento</button>`)+`<div class="calendar-layout"><section class="panel calendar-panel"><div class="panel-header"><div><h2 class="month-title">${monthText}</h2><p>${monthItems.filter(x=>x.kind==='match').length} ${monthItems.filter(x=>x.kind==='match').length===1?'partido':'partidos'} · ${monthItems.filter(x=>x.kind==='event').length} ${monthItems.filter(x=>x.kind==='event').length===1?'evento':'eventos'}</p></div><div class="actions"><button class="iconbtn" data-action="month-prev" aria-label="Mes anterior">${icon('left')}</button><button class="text-button" data-action="calendar-today">Hoy</button><button class="iconbtn" data-action="month-next" aria-label="Mes siguiente">${icon('chevron')}</button></div></div><div class="filterbar calendar-filters">${[['all','Todo'],['matches','Partidos'],['events','Eventos']].map(([k,l])=>`<button class="chip ${calendarType===k?'active':''}" data-calendar-type="${k}">${l}</button>`).join('')}<span class="calendar-legend"><i class="match-dot"></i>Partido <i class="event-dot"></i>Evento</span></div><div class="calendar-weekdays" aria-hidden="true">${['Lun','Mar','Mié','Jue','Vie','Sáb','Dom'].map(d=>`<span>${d}</span>`).join('')}</div><div class="calendar-grid">${days.map(d=>{const items=agendaItems(db,d,calendarType);return `<div class="calendar-cell ${d.startsWith(calendarMonth)?'':'other-month'} ${d===calendarDate?'selected':''} ${d===today()?'is-today':''}"><button class="calendar-date" data-calendar-date="${d}" aria-label="Ver agenda del ${dateLabel(d,{day:'numeric',month:'long',year:'numeric'})}" aria-pressed="${d===calendarDate}">${Number(d.slice(-2))}<span class="mobile-item-count">${items.length||''}</span></button><div class="calendar-cell-items">${items.slice(0,3).map(x=>`<button class="calendar-item ${x.kind} ${x.status==='cancelled'?'cancelled':''}" data-action="${x.kind==='match'?'calendar-match':'view-event'}" data-id="${x.id}" title="${esc(x.time+' '+x.title)}" aria-label="${esc(x.time+' '+x.title)}"><span>${esc(x.time)}</span><b>${esc(x.title)}</b></button>`).join('')}${items.length>3?`<button class="calendar-more" data-calendar-date="${d}">+${items.length-3} más</button>`:''}</div></div>`}).join('')}</div></section><aside class="calendar-day-panel panel"><div class="panel-header"><div><div class="eyebrow">AGENDA DEL DÍA</div><h2 style="margin-top:8px">${dateLabel(calendarDate,{weekday:'long',day:'numeric',month:'long'})}</h2></div></div><div class="day-agenda">${dayAgenda()}</div><div class="panel-footer"><button class="btn secondary small" data-action="new-event">${icon('plus')}Evento en este día</button></div></aside></div><div class="calendar-help">${icon('info')}Las horas corresponden a Costa Rica. Los avisos aparecen al abrir la beta. Exporte un evento a su calendario para programar una notificación en su dispositivo.</div><div class="section-title"><h2>Recordatorios</h2><button class="text-button" data-action="open-reminders">Ver todos </button></div>${reminderCards(dueReminders(db.calendarEvents).slice(0,3))}`}
function dayAgenda(){const items=agendaItems(db,calendarDate,calendarType);return items.length?items.map(x=>`<article class="day-agenda-item ${x.kind}"><div class="day-agenda-time">${icon(x.kind==='match'?'calendar':'bell')}${esc(x.time)}–${endTime(x.time,x.duration)}${x.status==='cancelled'?badge('Cancelado','gray'):''}</div><h3>${esc(x.title)}</h3><p>${esc(x.venue||'Lugar por confirmar')}</p><button class="text-button" data-action="${x.kind==='match'?'calendar-match':'view-event'}" data-id="${x.id}">${x.kind==='match'?'Ver partido y árbitros':'Ver evento'} </button></article>`).join(''):emptyState('No hay actividades en este día.','Puede agregar una reunión, capacitación u otro evento.','calendar')}
function reminderBanner(){const due=dueReminders(db.calendarEvents);return due.length?`<div class="callout reminder-banner">${icon('bell')}<div><strong>${due.length===1?'Tiene un recordatorio por revisar':`Tiene ${due.length} recordatorios por revisar`}</strong><p>${due.slice(0,2).map(e=>esc(e.title)+' · '+dateLabel(e.date)).join(' / ')}</p></div><div class="actions"><button class="btn secondary small" data-action="open-reminders">Ver recordatorios </button></div></div>`:''}
function reminderCards(events){return events.length?`<div class="event-grid">${events.map(e=>`<article class="event-card"><div class="match-top">${badge(e.status==='cancelled'?'Cancelado':e.reminderSeen?'Aviso visto':'Recordatorio',e.status==='cancelled'?'gray':e.reminderSeen?'green':'amber')}<span class="subtle">${dateLabel(e.date)} · ${esc(e.time)}</span></div><h3>${esc(e.title)}</h3><p>${esc(e.venue||'Lugar por confirmar')}</p><div class="actions"><button class="btn secondary small" data-action="view-event" data-id="${e.id}">Ver evento</button>${!e.reminderSeen&&e.status!=='cancelled'?`<button class="text-button" data-action="reminder-seen" data-id="${e.id}">Marcar visto</button>`:''}</div></article>`).join('')}</div>`:emptyState('No tiene avisos pendientes.','Los eventos con aviso previo aparecerán aquí cuando llegue el momento.','bell')}
function remindersPage(){const due=dueReminders(db.calendarEvents),next=db.calendarEvents.filter(e=>e.status!=='cancelled'&&e.reminderDays!==null&&eventEnd(e)>new Date()&&!due.includes(e)).sort((a,b)=>eventStart(a)-eventStart(b));return head('AVISOS DE LA ASOCIACIÓN','Recordatorios','Revise los avisos de sus eventos y marque los que ya vio.',`<button class="btn secondary" data-view="calendar">${icon('calendar')}Ver calendario</button>`)+reminderCards(due)+`<div class="section-title"><h2>Próximos eventos con aviso</h2></div>${reminderCards(next)}<p class="privacy-note">Los avisos de la beta se consultan al abrirla. Para recibir una notificación con la beta cerrada, abra el evento y exporte el archivo a su calendario. La entrega depende de la aplicación de calendario que utilice.</p>`}
function eventModal(id){const e=db.calendarEvents.find(e=>e.id===id);if(!e)return;openModal('Evento del calendario',`<div class="eyebrow">${esc(e.category)}</div><h2 style="margin:12px 0">${esc(e.title)}</h2><p class="hint">${dateLabel(e.date,{weekday:'long',day:'numeric',month:'long',year:'numeric'})}<br>${esc(e.time)}–${endTime(e.time,e.duration)} · Hora de Costa Rica<br>${esc(e.venue||'Lugar por confirmar')}</p>${e.notes?`<p class="event-notes">${esc(e.notes)}</p>`:''}${badge(e.status==='cancelled'?'Evento cancelado':e.reminderDays===null?'Sin aviso previo':e.reminderDays===0?'Aviso al comenzar':`Aviso ${e.reminderDays} ${e.reminderDays===1?'día':'días'} antes`,e.status==='cancelled'?'gray':'green')}<p class="hint" style="margin-top:18px">El aviso aparece en el resumen y en el calendario al abrir la beta. Al exportar, el archivo incluye la alarma para que su aplicación de calendario pueda programarla.</p><div class="actions"><button class="btn primary small" data-action="edit-event" data-id="${e.id}">Editar evento</button><button class="btn secondary small" data-action="export-event" data-id="${e.id}">${icon('download')}Exportar a calendario</button>${!e.reminderSeen&&e.status!=='cancelled'&&e.reminderDays!==null?`<button class="text-button" data-action="reminder-seen" data-id="${e.id}">Marcar aviso visto</button>`:''}</div><div class="modal-foot"><button class="btn secondary" data-action="close">Cerrar</button></div>`)}
function eventForm(id){const e=db.calendarEvents.find(e=>e.id===id);openModal(e?'Editar evento':'Nuevo evento',`<p class="hint">Agregue una reunión, capacitación u otra actividad de la asociación. Horarios de Costa Rica.</p><form id="event-form" data-id="${e?.id||''}"><div class="form-grid"><label class="field full">Nombre del evento<input name="title" value="${esc(e?.title||'')}" maxlength="100" required></label><label class="field">Tipo de evento<select name="category">${['Reunión','Capacitación','Actividad','Otro'].map(c=>`<option ${e?.category===c?'selected':''}>${c}</option>`).join('')}</select></label><label class="field">Fecha<input name="date" type="date" value="${e?.date||calendarDate}" required></label><label class="field">Hora de inicio<input name="time" type="time" value="${e?.time||'18:00'}" required></label><label class="field">Duración (minutos)<input name="duration" type="number" min="15" max="720" step="15" value="${e?.duration||60}" required></label><label class="field full">Lugar<input name="venue" value="${esc(e?.venue||'')}" maxlength="150" placeholder="Ej. Sala de reuniones o enlace de videollamada"></label><label class="field full">Recordarme<select name="reminder" aria-label="Recordarme"><option value="none" ${e&&e.reminderDays===null?'selected':''}>Sin aviso</option>${[[0,'Al comenzar'],[1,'1 día antes'],[2,'2 días antes'],[3,'3 días antes'],[7,'1 semana antes']].map(([n,l])=>`<option value="${n}" ${(e?e.reminderDays===n:n===2)?'selected':''}>${l}</option>`).join('')}</select><small>El aviso aparece dentro de la beta. Puede exportarlo a su calendario para recibir notificaciones.</small></label><label class="field full">Notas<textarea name="notes" rows="3" maxlength="1000">${esc(e?.notes||'')}</textarea></label>${e?`<label class="field full">Estado<select name="status"><option value="scheduled" ${e.status!=='cancelled'?'selected':''}>Programado</option><option value="cancelled" ${e.status==='cancelled'?'selected':''}>Cancelado</option></select></label>`:''}</div>${formFoot(e?'Guardar cambios':'Crear evento')}</form>`)}
function exportEvent(id){const e=db.calendarEvents.find(e=>e.id===id);if(!e)return;const blob=new Blob([calendarICS([e])],{type:'text/calendar;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='A-evento.ics';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Evento exportado. Impórtelo en su calendario para activar el aviso.');}

function sidePanel(empty) {
 const matches=weekMatches(),pending=matches.flatMap(m=>m.slots).filter(s=>s.status==='pending').length;
 const next=!matches.length
  ? {title:'Organice su próxima jornada',note:'Registre los partidos que recibió del organizador para comenzar a nombrar árbitros.',label:'Nuevo partido',action:'new-match'}
  : empty
   ? {title:`${empty} ${empty===1?'puesto por cubrir':'puestos por cubrir'}`,note:'Revise la disponibilidad y elija a quién enviar cada invitación.',label:'Asignar árbitros',action:'unfilled'}
   : pending
    ? {title:`${pending} ${pending===1?'respuesta pendiente':'respuestas pendientes'}`,note:'Consulte qué árbitros todavía deben responder a sus invitaciones.',label:'Ver invitaciones',action:'summary-invitations'}
    : {title:'Equipos arbitrales confirmados',note:'Consulte quiénes estarán a cargo de los partidos de esta semana.',label:'Ver equipos',action:'summary-crews'};
 return `<aside class="side-stack"><section class="insight"><div class="eyebrow">POR HACER</div><h2>${next.title}</h2><p>${next.note}</p><button class="btn primary" data-action="${next.action}">${next.label}</button></section><section class="panel"><div class="panel-header"><h2>Árbitros</h2><button class="text-button" data-view="refs">Ver todos</button></div><div class="side-list">${db.refs.slice(0,4).map(r=>`<button class="side-row" data-action="see-availability" data-id="${r.id}"><span class="avatar">${initials(r.name)}</span><span><b>${esc(r.name)}</b><small>${Object.keys(r.availability).filter(d=>d>=week&&d<=addDays(week,6)).length} días disponibles esta semana</small></span></button>`).join('')}</div></section><section class="panel"><div class="panel-header"><h2>Actividad reciente</h2></div><div class="activity">${db.events.slice(0,4).map(e=>`<div class="activity-item"><i></i><div><b>${esc(e.text)}</b><br><span>${new Date(e.at).toLocaleTimeString('es-CR',{hour:'2-digit',minute:'2-digit',timeZone:'America/Costa_Rica'})}</span></div></div>`).join('')}</div></section></aside>`;
}
function emptyState(title,subtitle='',ico='calendar'){return `<div class="empty">${icon(ico)}<b>${title}</b>${subtitle}</div>`}
function tournamentsPage(){return head('COMPETICIONES','Torneos','Defina el panel de árbitros disponible para cada competición.',`<button class="btn primary" data-action="new-tournament">${icon('plus')}Nuevo torneo</button>`)+`<div class="tournament-grid">${db.tournaments.map(t=>`<article class="tournament-card"><div class="trophy">${icon('trophy')}</div><span class="eyebrow">${esc(t.category)}</span><h2 style="margin-top:10px">${esc(t.name)}</h2><p>${esc(t.organizer)}</p><p class="tournament-email">${icon('mail')}${esc(t.reportEmail||'Correo de informes pendiente')}</p><div class="numbers"><div><b>${liveMatches(db).filter(m=>m.tournament===t.id).length}</b><small>Partidos</small></div><div><b>${t.refs.length}</b><small>Árbitros en el panel</small></div></div><div class="actions"><button class="btn secondary small" data-action="edit-tournament" data-id="${t.id}">Editar torneo</button><button class="btn primary small" data-action="new-match" data-id="${t.id}">${icon('plus')}Partido</button></div></article>`).join('')}</div><p class="privacy-note">En esta beta, la asociación registra los partidos recibidos del organizador. El portal del organizador queda para una etapa posterior.</p>`}
function refsPage(){const refs=db.refs.filter(r=>refScope==='all'||Object.keys(r.availability).some(d=>d>=week&&d<=addDays(week,6)));return head('EQUIPO ARBITRAL',refScope==='available'?'Árbitros con disponibilidad':'Árbitros','Consulte los días disponibles de cada integrante del panel.',`<button class="btn primary" data-action="new-ref">${icon('plus')}Agregar árbitro</button>`)+`<div class="toolbar">${weekButtons()}<label class="compact-label">Mostrar<select id="ref-scope" aria-label="Mostrar árbitros"><option value="all" ${refScope==='all'?'selected':''}>Todo el panel</option><option value="available" ${refScope==='available'?'selected':''}>Con disponibilidad esta semana</option></select></label><span class="subtle">${refs.length} árbitros</span></div><div class="ref-grid">${refs.map(r=>`<article class="ref-card"><div class="person"><span class="avatar">${initials(r.name)}</span><div><b>${esc(r.name)}</b><div class="subtle" style="margin-top:4px">${esc(r.level)}</div></div></div><p>${esc(r.email)}</p><p>${db.tournaments.filter(t=>t.refs.includes(r.id)).length} torneos · ${liveMatches(db).flatMap(m=>m.slots).filter(s=>s.ref===r.id&&s.status==='accepted').length} nombramientos confirmados</p>${badge(`${Object.keys(r.availability).filter(d=>d>=week&&d<=addDays(week,6)).length} días disponibles`,'green')}<div class="actions" style="margin-top:17px"><button class="btn secondary small" data-action="see-availability" data-id="${r.id}">Ver disponibilidad</button><button class="text-button" data-action="as-ref" data-id="${r.id}">Probar su perfil </button></div></article>`).join('')||emptyState('No hay árbitros disponibles en esta semana.','Cambie la semana o revise todo el panel.','people')}</div>`}
function availabilityRows(r,readonly=false){return Array.from({length:7},(_,i)=>{const date=addDays(week,i),a=r.availability[date];return `<div class="availability-day"><input type="checkbox" name="day-${date}" id="day-${date}" data-availability="${date}" ${a?'checked':''} ${readonly?'disabled':''} aria-label="Disponible el ${dateLabel(date)}"><label for="day-${date}">${dateLabel(date,{weekday:'long'})}<small>${dateLabel(date,{day:'numeric',month:'long'})}</small></label><input type="time" name="start-${date}" aria-label="Inicio de disponibilidad ${date}" value="${a?.start||'06:00'}" ${!a||readonly?'disabled':''} required><span class="subtle">a</span><input type="time" name="end-${date}" aria-label="Fin de disponibilidad ${date}" value="${a?.end||'22:00'}" ${!a||readonly?'disabled':''} required></div>`}).join('')}
function availabilityPage(){const r=db.refs.find(r=>r.id===refId);return head('SU SEMANA','¿Cuándo puede ir a la cancha?','Marque los días y las horas en los que puede arbitrar.')+`<section class="panel"><div class="panel-header"><div><h2>Disponibilidad semanal</h2><p>${esc(r.name)}</p></div>${weekButtons()}</div><form id="availability-form" class="availability"><div class="availability-help">Incluya tiempo suficiente para arbitrar el partido completo. Los administradores usarán esta información para proponerle nombramientos.</div>${availabilityRows(r)}<p class="form-error" id="availability-error" role="alert"></p><div class="actions" style="margin-top:20px"><button class="btn primary" type="submit">${icon('check')}Guardar disponibilidad</button><button class="btn secondary" type="button" data-action="weekend">Marcar fin de semana</button></div></form></section><p class="privacy-note">Cambiar su disponibilidad no cancela nombramientos confirmados. Si necesita un reemplazo, comuníquese con la asociación.</p>`}
function refereeHome(){const r=db.refs.find(r=>r.id===refId),mine=sorted(liveMatches(db)).flatMap(m=>m.slots.filter(s=>s.ref===refId&&active(s)).map(s=>({m,s}))),pending=mine.filter(x=>x.s.status==='pending'),accepted=mine.filter(x=>x.s.status==='accepted');return head('PORTAL DEL ÁRBITRO',`Hola, ${esc(r.name.split(' ')[0])}.`,'Sus invitaciones y próximos partidos, siempre a mano.')+`<div class="callout">${icon('calendar')}<div><strong>Su disponibilidad ayuda a organizar la jornada.</strong><p>Revise sus días disponibles antes de recibir un nuevo nombramiento.</p></div><div class="actions"><button class="btn secondary small" data-view="availability">Actualizar disponibilidad </button></div></div><div class="stats">${stat('Invitaciones por responder',pending.length,'Confirme o rechace cada solicitud','mail','ref-pending')}${stat('Partidos confirmados',accepted.length,'Consulte el día, la hora y el lugar','calendar','ref-accepted')}${stat('Honorarios confirmados',money(accepted.reduce((a,x)=>a+x.s.fee,0)),'Suma de sus nombramientos aceptados','wallet','ref-payments')}${stat('Días disponibles',Object.keys(r.availability).filter(d=>d>=week&&d<=addDays(week,6)).length,'En la semana actual del panel','clock','ref-availability')}</div>${refTab!=='accepted'?`<div class="section-title"><h2>Invitaciones pendientes</h2>${badge(`${pending.length} por responder`,'amber')}</div><div class="ref-matches">${pending.length?pending.map(x=>refMatch(x.m,x.s)).join(''):emptyState('Está al día.','Aquí aparecerán sus próximas invitaciones.','check')}</div>`:''}${refTab!=='pending'?`<div class="section-title"><h2>Sus partidos confirmados</h2></div><div class="ref-matches">${accepted.length?accepted.map(x=>refMatch(x.m,x.s)).join(''):emptyState('Todavía no hay nombramientos confirmados.','Acepte una invitación para ver aquí el partido.')}</div>`:''}${refereeChanges()}<p class="privacy-note">Las invitaciones de esta demostración aparecen dentro de la aplicación. No se envían correos ni mensajes.</p>`}
function mapLinks(m){const coordinates=m.lat!==null&&m.lng!==null;return `<a class="btn secondary small" href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(coordinates?`${m.lat},${m.lng}`:m.venue)}" target="_blank" rel="noopener noreferrer">${icon('pin')}Google Maps</a><a class="btn secondary small" href="https://www.waze.com/ul?${coordinates?`ll=${encodeURIComponent(`${m.lat},${m.lng}`)}&navigate=yes`:`q=${encodeURIComponent(m.venue)}&navigate=yes`}" target="_blank" rel="noopener noreferrer">${icon('pin')}Waze</a>`}
function refMatch(m,s){return `<article class="ref-match">${s.status==='pending'&&m.lastChange?`<div class="match-change-notice">${m.lastChange.action==='reschedule'?'Partido reprogramado':m.lastChange.action==='restore'?'Partido restaurado':'Datos del partido actualizados'}. Revise los datos y confirme de nuevo.${m.lastChange.action==='reschedule'?`<br>Antes: ${dateLabel(m.lastChange.fromDate)} · ${esc(m.lastChange.fromTime)}`:''}</div>`:''}<div class="match-top"><span class="tournament-tag">${esc(tournament(m)?.name)}</span>${statusBadge(s.status)}</div><div class="teams">${esc(m.home)}<span class="versus">vs</span>${esc(m.away)}</div><div class="subtle">Árbitro ${esc(s.role.toLowerCase())}</div><div class="match-meta"><span>${icon('calendar')}${dateLabel(m.date,{weekday:'long',day:'numeric',month:'long'})}</span><span>${icon('clock')}${esc(m.time)}–${endTime(m.time,m.duration)}</span></div><div class="match-meta"><span>${icon('pin')}${esc(m.venue)}</span></div><div class="fee">${money(s.fee)}<small>Honorarios de su nombramiento</small></div>${s.status==='pending'?`<div class="actions"><button class="btn primary small" data-action="accept" data-id="${m.id}" data-slot="${s.id}">${icon('check')}Aceptar partido</button><button class="btn danger small" data-action="reject" data-id="${m.id}" data-slot="${s.id}">Rechazar</button></div>`:`<div class="actions">${mapLinks(m)}${reportUI.button(m)}</div><p class="subtle" style="line-height:1.6">${m.lat===null?'La ubicación abre una búsqueda por nombre; confirme la cancha con la asociación.':'Punto de demostración. Confirme la entrada de la cancha con la asociación.'}</p>`}</article>`}
function financePage(){const t=totals(db);return head('CONTROL ECONÓMICO','Cobros y pagos','Registre los cobros a organizadores y los pagos a su equipo.',`<button class="btn secondary" data-action="export">${icon('download')}Exportar CSV</button>`)+`<div class="stats">${stat('Por cobrar',money(t.receivable),'Partidos pendientes de cobro','wallet','finance-charges-pending')}${stat('Por pagar a árbitros',money(t.payable),'Solo nombramientos confirmados','people','finance-payments-pending')}${stat('Pagado a árbitros',money(t.paid),'Pagos marcados en este registro','check','finance-payments-paid')}${stat('Cobrado',money(db.matches.filter(m=>m.collected).reduce((a,m)=>a+m.charge,0)),'Cobros marcados como recibidos','wallet','finance-charges-collected')}</div><div class="toolbar"><button class="btn ${financeTab==='charges'?'primary':'secondary'}" data-finance="charges">Cobros por partido</button><button class="btn ${financeTab==='payments'?'primary':'secondary'}" data-finance="payments">Pagos a árbitros</button><label class="subtle">Torneo <select id="finance-filter" aria-label="Filtrar cobros por torneo"><option value="all">Todos los torneos</option>${db.tournaments.map(t=>`<option value="${t.id}" ${tournamentFilter===t.id?'selected':''}>${esc(t.name)}</option>`).join('')}</select></label><label class="compact-label">Estado<select id="finance-state" aria-label="Estado de los cobros o pagos"><option value="all" ${financeState==='all'?'selected':''}>Todos</option><option value="pending" ${financeState==='pending'?'selected':''}>${financeTab==='charges'?'Por cobrar':'Por pagar'}</option><option value="done" ${financeState==='done'?'selected':''}>${financeTab==='charges'?'Cobrado':'Pagado'}</option></select></label></div><section class="panel"><div class="table-wrap">${financeTab==='charges'?chargesTable():paymentsTable()}</div></section><div class="footnote">${icon('info')}Este es un registro administrativo: marcar un pago no ejecuta transferencias bancarias ni emite facturas. Los totales incluyen todos los torneos y conservan los cobros y pagos registrados de partidos eliminados.</div>`}
function chargesTable(){return `<table><thead><tr><th>Partido / torneo</th><th>Fecha</th><th>Cobro al organizador</th><th>Estado</th><th>Acción</th></tr></thead><tbody>${sorted(chargeMatches(db)).filter(m=>(tournamentFilter==='all'||m.tournament===tournamentFilter)&&(financeState==='all'||(financeState==='done'?m.collected:!m.collected))).map(m=>`<tr><td>${esc(m.home)} vs ${esc(m.away)}<small>${esc(tournament(m)?.name)}${m.deletedAt?' · Partido eliminado':''}</small></td><td>${dateLabel(m.date)}</td><td class="cash-value">${money(m.charge)}</td><td>${badge(m.collected?'Cobrado':'Por cobrar',m.collected?'green':'amber')}</td><td><button class="btn secondary small" data-action="collect" data-id="${m.id}">${m.collected?'Deshacer cobro':'Marcar cobrado'}</button></td></tr>`).join('')||'<tr><td colspan="5">No hay cobros con los filtros seleccionados.</td></tr>'}</tbody></table>`}
function paymentStatus(slot){
 if(!slot.paid)return badge('Pendiente','amber');
 const recordedBy=slot.paidBy==='ref'?'Confirmado por el árbitro':slot.paidBy==='admin'?'Registrado por administración':'';
 return `${badge('Pagado','green')}${recordedBy?`<small>${recordedBy}</small>`:''}`;
}
function paymentsTable(){
 const items=paymentRows(db).filter(({m,s})=>(tournamentFilter==='all'||m.tournament===tournamentFilter)&&(financeState==='all'||(financeState==='done'?s.paid:!s.paid))).sort((a,b)=>(a.m.date+a.m.time).localeCompare(b.m.date+b.m.time));
 return `<table><thead><tr><th>Árbitro</th><th>Partido</th><th>Honorarios</th><th>Estado</th><th>Acción</th></tr></thead><tbody>${items.map(({m,s})=>`<tr><td>${esc(refName(s.ref))}<small>${esc(s.role)}</small></td><td>${esc(m.home)} vs ${esc(m.away)}<small>${dateLabel(m.date)}${m.deletedAt?' · Partido eliminado':s.status!=='accepted'?' · Confirmación pendiente':''}</small></td><td class="cash-value">${money(s.fee)}</td><td>${paymentStatus(s)}</td><td><button class="btn secondary small" data-action="${s.paid?'undo-payment':'mark-payment'}" data-id="${m.id}" data-slot="${s.id}">${s.paid?'Deshacer pago':'Marcar pagado'}</button></td></tr>`).join('')||'<tr><td colspan="5">No hay pagos con los filtros seleccionados.</td></tr>'}</tbody></table>`;
}
function refHistory(){
 const items=paymentRows(db).filter(({s})=>s.ref===refId).sort((a,b)=>(a.m.date+a.m.time).localeCompare(b.m.date+b.m.time));
 const paid=items.filter(({s})=>s.paid).reduce((sum,{s})=>sum+s.fee,0);
 const due=items.filter(({s})=>!s.paid).reduce((sum,{s})=>sum+s.fee,0);
 const visible=items.filter(({s})=>refPaymentState==='all'||(refPaymentState==='done'?s.paid:!s.paid));
 return head('SUS HONORARIOS','Mis pagos','Confirme el pago del partido cuando reciba el depósito.')+`<div class="stats">${stat('Pendiente de pago',money(due),'Según el registro de la asociación','wallet','ref-history-pending')}${stat('Pagos registrados',money(paid),'Confirmados por usted o por administración','check','ref-history-paid')}</div><div class="toolbar"><label class="compact-label">Estado<select id="ref-payment-state" aria-label="Estado de mis pagos"><option value="all" ${refPaymentState==='all'?'selected':''}>Todos</option><option value="pending" ${refPaymentState==='pending'?'selected':''}>Pendientes</option><option value="done" ${refPaymentState==='done'?'selected':''}>Pagados</option></select></label></div><section class="panel"><div class="table-wrap"><table><thead><tr><th>Partido</th><th>Fecha / puesto</th><th>Honorarios</th><th>Estado</th></tr></thead><tbody>${visible.map(({m,s})=>`<tr><td>${esc(m.home)} vs ${esc(m.away)}<small>${esc(tournament(m)?.name)}${m.deletedAt?' · Partido eliminado':''}</small></td><td>${dateLabel(m.date)}<small>${esc(s.role)}</small></td><td>${money(s.fee)}</td><td>${s.paid?paymentStatus(s):`<button class="btn secondary small" data-action="confirm-payment" data-id="${m.id}" data-slot="${s.id}">Confirmar pago recibido</button>`}</td></tr>`).join('')||'<tr><td colspan="4">No hay honorarios con este estado.</td></tr>'}</tbody></table></div></section><p class="privacy-note">El registro de la aplicación no sustituye un comprobante bancario. Consulte cualquier diferencia con la asociación.</p>`;
}

function openModal(title,html){$('#modal').setAttribute('aria-labelledby','modal-title');$('#modal').innerHTML=`<div class="modal-head"><h2 id="modal-title">${title}</h2><button class="iconbtn" data-action="close" aria-label="Cerrar">${icon('close')}</button></div><div class="modal-body">${html}</div>`;if(!$('#modal').open)$('#modal').showModal();$('#modal').scrollTop=0;$('#modal').querySelector('[data-action="close"]')?.focus({preventScroll:true});}
const formFoot=(label='Guardar')=>`<p id="modal-error" class="form-error" role="alert"></p><div class="modal-foot"><button type="button" class="btn secondary" data-action="close">Cancelar</button><button type="submit" class="btn primary">${label}</button></div>`;
let pendingMatchPlan=null;
function matchEditForm(id,mode='edit',draft=null){
 if(role!=='admin')return toast('Esta opción corresponde al administrador.');
 const original=db.matches.find(m=>m.id===id);if(!original||original.deletedAt)return toast('Este partido ya no está activo.');
 const m=draft||original,reschedule=mode==='reschedule';
 openModal(reschedule?'Reprogramar partido':'Editar partido',`<div class="tournament-tag">${esc(m.home)} vs ${esc(m.away)}</div><p class="hint" style="margin-top:13px">${reschedule?'Elija la nueva fecha, hora o cancha.':'Actualice los datos del partido.'} Antes de guardar verá los cambios y sus efectos sobre el equipo arbitral. Las horas corresponden a Costa Rica.</p><form id="match-edit-form" data-id="${m.id}" data-mode="${mode}" data-origin="${view}"><div class="form-grid">${!reschedule?`<label class="field full">Torneo<select name="tournament" aria-label="Torneo" required>${db.tournaments.map(t=>`<option value="${t.id}" ${t.id===m.tournament?'selected':''}>${esc(t.name)}</option>`).join('')}</select></label><label class="field">Equipo local<input name="home" value="${esc(m.home)}" maxlength="70" required></label><label class="field">Equipo visitante<input name="away" value="${esc(m.away)}" maxlength="70" required></label>`:''}<label class="field">Fecha<input name="date" type="date" value="${m.date}" required></label><label class="field">Hora de inicio<input name="time" type="time" value="${m.time}" required></label><label class="field">Bloque del partido (minutos)<input name="duration" type="number" min="30" max="240" step="5" value="${m.duration}" required></label><label class="field full">Cancha y localidad<input name="venue" value="${esc(m.venue)}" maxlength="150" required></label><label class="field">Latitud (opcional)<input name="lat" type="number" min="-90" max="90" step="any" value="${m.lat??''}"></label><label class="field">Longitud (opcional)<input name="lng" type="number" min="-180" max="180" step="any" value="${m.lng??''}"></label>${!reschedule?`<label class="field">Cobro al organizador (₡)<input name="charge" type="number" min="0" max="10000000" step="1" value="${m.charge}" ${original.collected?'readonly':''} required>${original.collected?'<small>Este cobro ya está registrado. Para corregir el importe, revierta primero el registro en Cobros y pagos.</small>':''}</label>` : ''}</div>${reschedule?'':teamFields(m,original)}<div class="form-grid"><label class="field full">Motivo del cambio (opcional)<textarea name="reason" maxlength="500" rows="2" placeholder="Ej. Nueva fecha solicitada por el organizador">${esc(draft?.editReason||'')}</textarea></label></div><div class="edit-explanation">${icon('info')}Los cambios de horario, cancha, torneo u honorarios requieren revisar las confirmaciones. Los puestos incompatibles quedarán libres; los movimientos económicos registrados se conservan.</div>${formFoot('Revisar cambios')}</form>`);
}
function matchValue(field,value){if(value===null||value===undefined||value==='')return 'Sin dato';if(field==='tournament')return esc(db.tournaments.find(t=>t.id===value)?.name||value);if(field==='date')return esc(dateLabel(value,{day:'numeric',month:'long',year:'numeric'}));if(['charge','fee'].includes(field))return money(value);if(field==='duration')return `${value} minutos`;return esc(value)}
function matchReview(plan){
 pendingMatchPlan=plan;
 const restoring=plan.kind==='restore',label=restoring?'Restaurar partido':plan.kind==='reschedule'?'Confirmar reprogramación':'Guardar cambios';
 openModal(restoring?'Revisar restauración':'Revisar cambios del partido',`<h3>${esc(plan.after.home)} vs ${esc(plan.after.away)}</h3><p class="hint" style="margin-top:12px">${restoring?'El partido volverá a la programación. Se revisa nuevamente la disponibilidad de sus árbitros.':'Revise el resultado antes de confirmar.'}</p>${plan.changes.length?`<div class="change-table"><div class="change-table-head"><span>Dato</span><span>Antes</span><span>Después</span></div>${plan.changes.map(c=>`<div><strong>${esc(c.label)}</strong><span>${matchValue(c.field,c.before)}</span><b>${matchValue(c.field,c.after)}</b></div>`).join('')}</div>`:`<p class="hint">${dateLabel(plan.after.date)} · ${plan.after.time} · ${esc(plan.after.venue)}</p>`}${plan.renewed.length?`<section class="change-impact"><h3>${plan.renewed.length} ${plan.renewed.length===1?'árbitro debe':'árbitros deben'} confirmar de nuevo</h3><ul>${plan.renewed.map(x=>`<li>${esc(refName(x.ref))} · ${esc(x.role)}</li>`).join('')}</ul></section>`:''}${plan.released.length?`<section class="change-impact warning"><h3>${plan.released.length} ${plan.released.length===1?'puesto quedará libre':'puestos quedarán libres'}</h3><ul>${plan.released.map(x=>`<li><strong>${esc(refName(x.ref))} · ${esc(x.role)}</strong><br>${esc(x.reason)}</li>`).join('')}</ul><p>Podrá nombrar reemplazos después de guardar.</p></section>`:''}${!plan.renewed.length&&!plan.released.length?'<p class="hint">No cambia ninguna confirmación arbitral.</p>':''}${plan.after.collected||plan.after.slots.some(s=>s.paid)?'<div class="edit-explanation">Los cobros y pagos ya registrados se conservarán.</div>':''}${plan.reason?`<p class="hint" style="margin-top:15px">Motivo: ${esc(plan.reason)}</p>`:''}<p id="modal-error" class="form-error" role="alert"></p><div class="modal-foot">${restoring?'<button class="btn secondary" data-action="close">Cancelar</button>':'<button class="btn secondary" data-action="back-match-edit">Volver a editar</button>'}<button class="btn primary" data-action="apply-match-update">${label}</button></div>`);
}
function matchHistory(m){const history=[...(m.history||[])].reverse();return `<details class="match-history"><summary>Historial del partido (${history.length})</summary>${history.length?history.map(h=>`<article><strong>${{edit:'Edición',reschedule:'Reprogramación',delete:'Eliminación',restore:'Restauración'}[h.action]||'Cambio'} · ${new Date(h.at).toLocaleString('es-CR',{timeZone:'America/Costa_Rica',dateStyle:'short',timeStyle:'short'})}</strong><small>Administrador</small>${h.before&&h.after?`<p>${dateLabel(h.before.date)} ${esc(h.before.time)} → ${dateLabel(h.after.date)} ${esc(h.after.time)}${h.before.venue!==h.after.venue?`<br>Cancha: ${esc(h.before.venue)} → ${esc(h.after.venue)}`:''}</p>`:''}${h.reason?`<p>${esc(h.reason)}</p>`:''}${h.renewed?.length?`<p>Nueva confirmación: ${h.renewed.map(x=>esc(refName(x.ref))).join(', ')}.</p>`:''}${h.released?.length?`<p>Puestos liberados: ${h.released.map(x=>esc(refName(x.ref))).join(', ')}.</p>`:''}</article>`).join(''):'<p class="hint">Este partido no tiene modificaciones registradas.</p>'}</details>`}
function deleteMatchModal(id){
 if(role!=='admin')return toast('Esta opción corresponde al administrador.');
 const m=db.matches.find(m=>m.id===id);if(!m||m.deletedAt)return;
 openModal('Eliminar partido',`<h3>${esc(m.home)} vs ${esc(m.away)}</h3><p class="hint" style="margin-top:13px">${dateLabel(m.date,{weekday:'long',day:'numeric',month:'long'})} · ${m.time}<br>${esc(m.venue)}</p><div class="delete-explanation">El partido saldrá de la programación, del calendario y de los nombramientos activos. Podrá recuperarlo en <strong>Partidos → Eliminados</strong>.</div>${m.collected||m.slots.some(s=>s.paid)?'<p class="hint" style="margin-top:15px">Los cobros y pagos registrados se conservarán en el historial económico.</p>':''}<form id="delete-match-form" data-id="${m.id}"><label class="field full" style="margin-top:18px">Motivo (opcional)<textarea name="reason" rows="2" maxlength="500" placeholder="Ej. Cancelado por el organizador"></textarea></label><p id="modal-error" class="form-error" role="alert"></p><div class="modal-foot"><button class="btn secondary" type="button" data-action="close">Conservar partido</button><button class="btn danger" type="submit">Eliminar partido</button></div></form>`);
}
function deletedMatchesPage(){const matches=sorted(db.matches.filter(m=>m.deletedAt));return head('PARTIDOS ELIMINADOS','Eliminados','Recupere un partido y revise su equipo arbitral antes de volver a programarlo.',`<button class="btn secondary" data-view="matches">${icon('left')}Volver a partidos</button>`)+`<div class="deleted-list">${matches.length?matches.map(m=>`<article class="panel deleted-match"><div class="match-top"><span class="tournament-tag">${esc(tournament(m)?.name)}</span>${badge('Eliminado','gray')}</div><h2>${esc(m.home)} vs ${esc(m.away)}</h2><p>${dateLabel(m.date)} · ${m.time} · ${esc(m.venue)}</p>${m.deletionReason?`<p class="subtle">Motivo: ${esc(m.deletionReason)}</p>`:''}${m.collected||m.slots.some(s=>s.paid)?'<p class="subtle">Conserva movimientos económicos registrados.</p>':''}<div class="actions"><button class="btn primary small" data-action="restore-match" data-id="${m.id}">${icon('restore')}Restaurar partido</button><button class="btn secondary small" data-action="deleted-details" data-id="${m.id}">Ver historial</button></div></article>`).join(''):emptyState('No hay partidos eliminados.','Los partidos que elimine aparecerán aquí para poder recuperarlos.','trash')}</div>`}
function deletedMatchDetails(id){const m=db.matches.find(m=>m.id===id);if(!m)return;openModal('Partido eliminado',`<h3>${esc(m.home)} vs ${esc(m.away)}</h3><p class="hint" style="margin-top:13px">${dateLabel(m.date)} · ${m.time}<br>${esc(m.venue)}</p>${matchHistory(m)}<div class="modal-foot"><button class="btn secondary" data-action="close">Cerrar</button><button class="btn primary" data-action="restore-match" data-id="${m.id}">Restaurar partido</button></div>`)}
function refereeChanges(){const notices=[];for(const m of db.matches){if(m.deletedAt&&m.slots.some(s=>s.ref===refId&&active(s)))notices.push({at:m.deletedAt,title:`${m.home} vs ${m.away}`,text:'Partido eliminado de la programación.',reason:m.deletionReason});if(!m.deletedAt){const h=[...(m.history||[])].reverse().find(x=>x.released?.some(r=>r.ref===refId));if(h&&!m.slots.some(s=>s.ref===refId&&active(s)))notices.push({at:h.at,title:`${m.home} vs ${m.away}`,text:'Su nombramiento fue liberado por un cambio del partido.',reason:h.released.find(x=>x.ref===refId).reason});}}return notices.length?`<div class="section-title"><h2>Últimos cambios de la asociación</h2></div><div class="ref-change-list">${notices.sort((a,b)=>b.at.localeCompare(a.at)).slice(0,5).map(n=>`<article><strong>${esc(n.title)}</strong><p>${esc(n.text)}</p>${n.reason?`<small>${esc(n.reason)}</small>`:''}</article>`).join('')}</div>`:''}

function positionOptions(tournamentId, slot, selected, index){
 const current=slot&&(active(slot)||slot.paid);
 const vacant=index?'Sin asistente':'Elegir después';
 const options=[];
 if(!slot?.paid&&(index>0||!current))options.push(['',vacant]);
 if(current)options.push(['keep',refName(slot.ref)]);
 else {
  if(slot&&index)options.push(['keep','Puesto por asignar']);
  const panel=db.tournaments.find(t=>t.id===tournamentId)?.refs||[];
  for(const ref of db.refs.filter(r=>panel.includes(r.id)))options.push([ref.id,ref.name]);
 }
 return options.map(([value,label])=>`<option value="${esc(value)}" ${value===selected?'selected':''}>${esc(label)}</option>`).join('');
}
function teamFields(draft, original){
 return `<fieldset class="form-section"><legend>Equipo arbitral</legend><p class="hint">Deje en blanco los asistentes que no necesite. Se invitará a los árbitros que elija al guardar.</p><div class="form-grid">${refereePositions.map((position,index)=>{
  const previous=original?.slots.find(s=>s.role===position);
  const current=draft.slots?.find(s=>s.role===position);
  const selected=draft.teamSelection?.[index]??(previous&&(index||active(previous)||previous.paid)?'keep':'');
  const isOptionalAndBlank=index>0&&!selected;
  return `<label class="field">${position}${index?' (opcional)':''}<select name="position-${index}" data-team-position="${index}">${positionOptions(draft.tournament,previous,selected,index)}</select></label><label class="field assistant-fee" data-team-fee="${index}" ${isOptionalAndBlank?'hidden':''}>Honorarios · ${position} (₡)<input name="fee-${index}" type="number" min="0" max="1000000" step="1" value="${current?.fee??previous?.fee??defaultFee(position)}" ${previous?.paid?'readonly':''} ${isOptionalAndBlank?'disabled':''} required></label>`;
 }).join('')}</div></fieldset>`;
}
function updateTeamFields(form, refreshPanel){
 const original=db.matches.find(m=>m.id===form.dataset.id);
 for(const select of form.querySelectorAll('[data-team-position]')){
  const index=Number(select.dataset.teamPosition);
  if(refreshPanel){
   const slot=original?.slots.find(s=>s.role===refereePositions[index]);
   select.innerHTML=positionOptions(form.elements.tournament.value,slot,select.value,index);
  }
  const fee=form.querySelector(`[data-team-fee="${index}"]`);
  const hidden=index>0&&!select.value;
  fee.hidden=hidden;
  fee.querySelector('input').disabled=hidden;
 }
}
function chosenTeam(data){
 const teamSelection=refereePositions.map((_,i)=>String(data.get(`position-${i}`)||''));
 const positions=[],fees={},invite={};
 refereePositions.forEach((position,i)=>{
  const selection=teamSelection[i];
  if(i>0&&!selection)return;
  positions.push(position);
  fees[position]=Number(data.get(`fee-${i}`));
  if(selection&&selection!=='keep')invite[position]=selection;
 });
 return {teamSelection,positions,fees,invite};
}
function matchModal(tournamentId) {
 if(!db.tournaments.length){toast('Primero cree un torneo.');return;}
 tournamentId=tournamentId||db.tournaments[0].id;
 openModal('Nuevo partido',`<p class="hint">Registre el partido y sus honorarios. Al guardarlo podrá elegir al equipo arbitral.</p><form id="match-form">
 <fieldset class="form-section"><legend>Datos del partido</legend><div class="form-grid"><label class="field full">Torneo<select name="tournament" required>${db.tournaments.map(t=>`<option value="${t.id}" ${t.id===tournamentId?'selected':''}>${esc(t.name)}</option>`).join('')}</select></label><label class="field">Equipo local<input name="home" maxlength="70" placeholder="Nombre del equipo" required></label><label class="field">Equipo visitante<input name="away" maxlength="70" placeholder="Nombre del equipo" required></label></div></fieldset>
 <fieldset class="form-section"><legend>Fecha y lugar</legend><div class="form-grid"><label class="field">Fecha<input name="date" type="date" value="${addDays(week,5)}" required></label><label class="field">Hora de inicio<input name="time" type="time" value="09:00" required></label><label class="field full">Tiempo reservado (minutos)<input name="duration" type="number" min="30" max="240" step="5" value="120" required><small>Incluya el tiempo completo que debe estar disponible el árbitro.</small></label><label class="field full">Cancha y localidad<input name="venue" maxlength="150" placeholder="Ej. Cancha Central, localidad" required></label></div><details class="optional-fields"><summary>Agregar coordenadas para la ubicación (opcional)</summary><div class="form-grid"><label class="field">Latitud<input name="lat" type="number" min="-90" max="90" step="any" placeholder="Ej. 10.3233"></label><label class="field">Longitud<input name="lng" type="number" min="-180" max="180" step="any" placeholder="Ej. -84.4307"></label></div></details></fieldset>
 <fieldset class="form-section"><legend>Cobro</legend><div class="form-grid"><label class="field full">Cobro al organizador (₡)<input name="charge" type="number" min="0" max="10000000" step="1" value="65000" required></label></div></fieldset>${teamFields({tournament:tournamentId})}${formFoot('Crear partido')}</form>`);
}
function tournamentModal(id){const t=db.tournaments.find(t=>t.id===id);openModal(t?'Editar torneo':'Nuevo torneo',`<p class="hint">Solo los árbitros del panel podrán recibir invitaciones de este torneo. Puede modificarlo después.</p><form id="tournament-form" data-id="${t?.id||''}"><div class="form-grid"><label class="field full">Nombre del torneo<input name="name" value="${esc(t?.name||'')}" maxlength="80" required></label><label class="field full">Organizador<input name="organizer" value="${esc(t?.organizer||'')}" maxlength="100" required></label><label class="field full">Modalidad y categoría<input name="category" value="${esc(t?.category||'Fútbol 11 · Libre')}" maxlength="80" required></label><label class="field full">Correo para recibir informes arbitrales<input name="reportEmail" type="email" maxlength="160" value="${esc(t?.reportEmail||'')}" placeholder="informes@campeonato.com"><small>Puede completarlo después. Se usará como destinatario al simular la entrega del informe de cada partido.</small></label><div class="field full">Panel de árbitros<div class="checkgrid">${db.refs.map(r=>`<label><input type="checkbox" name="refs" value="${r.id}" ${!t||t.refs.includes(r.id)?'checked':''}>${esc(r.name)}</label>`).join('')}</div></div></div>${formFoot(t?'Guardar cambios':'Crear torneo')}</form>`)}
function refModal(){openModal('Agregar árbitro',`<p class="hint">Se creará un perfil de demostración. No se enviará una invitación por correo.</p><form id="ref-form"><div class="form-grid"><label class="field full">Nombre completo<input name="name" maxlength="80" required></label><label class="field full">Correo electrónico<input name="email" type="email" maxlength="120" required></label><label class="field full">Categoría<select name="level"><option>Primera categoría</option><option>Segunda categoría</option><option>En formación</option></select></label></div>${formFoot('Agregar al panel')}</form>`)}
function assignmentModal(id){const m=db.matches.find(m=>m.id===id);if(!m)return toast('No se encontró el partido.');if(m.deletedAt)return deletedMatchDetails(id);openModal('Equipo arbitral',`<div class="tournament-tag">${esc(tournament(m)?.name)}</div><h3 style="margin:12px 0">${esc(m.home)} vs ${esc(m.away)}</h3><p class="hint">${dateLabel(m.date,{weekday:'long',day:'numeric',month:'long'})} · ${esc(m.time)}–${endTime(m.time,m.duration)}<br>${esc(m.venue)}<br>Se comprueba disponibilidad completa y un margen provisional de 45 minutos entre nombramientos. La categoría se muestra para que el administrador decida.</p><div class="match-management detail-management">${reportUI.button(m)}<button class="btn secondary small" data-action="edit-match" data-id="${m.id}">${icon('edit')}Editar partido</button><button class="btn secondary small" data-action="reschedule-match" data-id="${m.id}">${icon('clock')}Reprogramar</button><button class="btn danger small" data-action="delete-match" data-id="${m.id}">${icon('trash')}Eliminar</button></div>${refereePositions.map((position,index)=>slotEditor(m,m.slots.find(s=>s.role===position)||{id:`optional-${index}`,role:position,fee:defaultFee(position),status:'empty'},!m.slots.some(s=>s.role===position))).join('')}${matchHistory(m)}<p class="form-error" id="modal-error" role="alert"></p><div class="modal-foot"><button class="btn secondary" data-action="close">Listo</button></div>`)}
function slotEditor(m,s,optional=false){if(s.paid&&!active(s))return `<div class="slot-card"><div class="slot-head"><strong>${esc(s.role)} · ${money(s.fee)}</strong>${badge('Pago registrado','green')}</div><p class="hint">${esc(refName(s.ref))}. Para cambiar este nombramiento, revierta primero el pago registrado en Cobros y pagos.</p></div>`;if(active(s))return `<div class="slot-card"><div class="slot-head"><strong>${esc(s.role)} · ${money(s.fee)}</strong>${statusBadge(s.status)}</div><div class="person"><span class="avatar">${initials(refName(s.ref))}</span><b>${esc(refName(s.ref))}</b></div>${s.status==='pending'&&!s.paid?`<button class="text-button" style="margin-top:12px" data-action="cancel-invite" data-id="${m.id}" data-slot="${s.id}">Retirar invitación</button>`:s.status==='pending'?'<p class="subtle" style="margin-bottom:0">Pago registrado. Esperando la nueva confirmación del árbitro.</p>':'<p class="subtle" style="margin-bottom:0">El árbitro ya aceptó el nombramiento.</p>'}</div>`;
 const candidates=db.refs.filter(r=>tournament(m)?.refs.includes(r.id)).map(r=>({r,...eligibility(db,r,m,s),load:liveMatches(db).flatMap(x=>x.slots).filter(x=>x.ref===r.id&&active(x)).length})).sort((a,b)=>Number(b.ok)-Number(a.ok)||a.load-b.load||a.r.name.localeCompare(b.r.name));
 return `<div class="slot-card"><div class="slot-head"><strong>${esc(s.role)} · ${money(s.fee)}</strong>${optional?badge('Opcional','gray'):statusBadge(s.status)}</div>${s.status==='rejected'?`<p class="hint" style="margin-bottom:10px">${esc(refName(s.ref))} rechazó esta invitación. Puede invitar a otra persona.</p>`:''}<div class="actions"><select id="candidate-${s.id}" aria-label="Árbitro para ${esc(s.role)}"><option value="">${optional?'Sin asistente':'Seleccione un árbitro disponible'}</option>${candidates.map(c=>`<option value="${c.r.id}" ${c.ok?'':'disabled'}>${esc(c.r.name)} · ${esc(c.r.level)} · ${c.ok?`${c.load} nombramientos activos`:esc(c.reason)}</option>`).join('')}</select><button class="btn primary small" data-action="send" data-id="${m.id}" data-slot="${s.id}" ${optional?`data-position="${esc(s.role)}"`:""}>Invitar</button></div>${!candidates.some(c=>c.ok)?'<p class="hint" style="margin:10px 0 0">No hay árbitros elegibles. Revise el panel del torneo o su disponibilidad.</p>':'<p class="subtle" style="margin-bottom:0">Disponibles ordenados por menor cantidad de nombramientos activos.</p>'}</div>`}
function exportCSV(){const lines=[['Tipo','Torneo','Partido','Fecha','Árbitro','Puesto','Monto CRC','Estado','Estado del partido']];chargeMatches(db).forEach(m=>lines.push(['Cobro',tournament(m)?.name,`${m.home} vs ${m.away}`,m.date,'','',m.charge,m.collected?'Cobrado':'Pendiente',m.deletedAt?'Eliminado':'Activo']));paymentRows(db).forEach(({m,s})=>lines.push(['Pago',tournament(m)?.name,`${m.home} vs ${m.away}`,m.date,refName(s.ref),s.role,s.fee,s.paid?'Pagado':'Pendiente',m.deletedAt?'Eliminado':'Activo']));const safe=v=>{const s=String(v??'');return '"'+(/^[=+@\-\t\r\n]/.test(s)?"'"+s:s).replace(/"/g,'""')+'"'};const url=URL.createObjectURL(new Blob(['\ufeff'+lines.map(r=>r.map(safe).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='A-cobros-y-pagos.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Registro exportado.');}
function navigate(name){if($('#modal').open)$('#modal').close();view=name;day='';query='';filter='all';matchPeriod='all';matchTournament='all';refScope='all';financeState='all';refPaymentState='all';refTab='all';if(name==='overview')week=monday(today());render();window.scrollTo({top:0});}
function extraAction(action,id){
 if(['edit-match','reschedule-match','delete-match','show-deleted-matches','deleted-details','restore-match','back-match-edit','apply-match-update'].includes(action)&&role!=='admin')throw Error('Esta acción corresponde al administrador.');
 switch(action){
 case 'edit-match':matchEditForm(id);return true;
 case 'reschedule-match':matchEditForm(id,'reschedule');return true;
 case 'delete-match':deleteMatchModal(id);return true;
 case 'show-deleted-matches':navigate('trash');return true;
 case 'deleted-details':deletedMatchDetails(id);return true;
 case 'restore-match':{const plan=prepareMatchUpdate(db,id,{},role,{restore:true});plan.returnView='matches';matchReview(plan);return true;}
 case 'back-match-edit':{const plan=pendingMatchPlan;if(plan)matchEditForm(plan.matchId,plan.kind,{...plan.after,editReason:plan.reason,teamSelection:plan.teamSelection});return true;}
 case 'apply-match-update':{const plan=pendingMatchPlan;if(!plan)throw Error('Abra el formulario para revisar los cambios.');const m=applyMatchUpdate(db,plan,role);pendingMatchPlan=null;log(`Partido ${plan.kind==='reschedule'?'reprogramado':plan.kind==='restore'?'restaurado':'actualizado'}: ${m.home} vs ${m.away}.`);$('#modal').close();if(plan.returnView==='calendar'){view='calendar';calendarDate=m.date;calendarMonth=m.date.slice(0,7);calendarType='all';}else{view='matches';matchPeriod='all';matchTournament='all';day='';query='';filter='all';}render();window.scrollTo({top:0});toast(plan.renewed.length?'Cambio guardado. Hay árbitros que deben confirmar de nuevo.':'Partido actualizado.');return true;}
 }

 const summary=()=>{week=monday(today());matchPeriod='week';matchTournament='all';day='';query='';filter='all';};
 switch(action){
 case 'summary-matches':summary();view='matches';break;
 case 'summary-crews':summary();view='crews';break;
 case 'summary-invitations':summary();view='invitations';break;
 case 'summary-refs':week=monday(today());refScope='available';view='refs';break;
 case 'open-reminders':view='reminders';break;
 case 'new-event':eventForm();return true;
 case 'edit-event':eventForm(id);return true;
 case 'view-event':eventModal(id);return true;
 case 'export-event':exportEvent(id);return true;
 case 'reminder-seen':{const e=db.calendarEvents.find(e=>e.id===id);if(e){e.reminderSeen=true;persist();if($('#modal').open)$('#modal').close();toast('Aviso marcado como visto.')}break}
 case 'calendar-match':assignmentModal(id);return true;
 case 'month-prev':case 'month-next':{const d=parseDate(calendarMonth+'-01');d.setMonth(d.getMonth()+(action==='month-next'?1:-1));calendarMonth=localDate(d).slice(0,7);calendarDate=calendarMonth+'-01';break}
 case 'calendar-today':calendarDate=today();calendarMonth=calendarDate.slice(0,7);break;
 case 'ref-pending':view='home';refTab='pending';break;
 case 'ref-accepted':view='home';refTab='accepted';break;
 case 'ref-payments':view='history';refPaymentState='all';break;
 case 'ref-availability':view='availability';week=monday(today());break;
 case 'ref-history-pending':refPaymentState='pending';break;
 case 'ref-history-paid':refPaymentState='done';break;
 case 'finance-charges-pending':tournamentFilter='all';financeTab='charges';financeState='pending';break;
 case 'finance-charges-collected':tournamentFilter='all';financeTab='charges';financeState='done';break;
 case 'finance-payments-pending':tournamentFilter='all';financeTab='payments';financeState='pending';break;
 case 'finance-payments-paid':tournamentFilter='all';financeTab='payments';financeState='done';break;
 default:return false;
 }
 render();window.scrollTo({top:0});return true;
}

document.addEventListener('click',event=>{
 const el=event.target.closest('button,[data-action]');if(!el)return;
 if(el.dataset.view){navigate(el.dataset.view);return}
 if(el.dataset.calendarDate){calendarDate=el.dataset.calendarDate;calendarMonth=calendarDate.slice(0,7);render();return}
 if(el.dataset.calendarType){calendarType=el.dataset.calendarType;render();return}
 if(el.dataset.filter){filter=el.dataset.filter;render();return}
 if(el.dataset.day){day=day===el.dataset.day?'':el.dataset.day;render();return}
 if(el.dataset.finance){financeTab=el.dataset.finance;financeState='all';render();return}
 const action=el.dataset.action,id=el.dataset.id,slotId=el.dataset.slot;
 try{if(action==='toggle-theme'){const saved=window.ATheme.toggle();el.setAttribute('aria-pressed',String(window.ATheme.get()==='dark'));if(!saved)toast('La apariencia se cambió para esta sesión. El navegador no permitió guardar la preferencia.');return;}if(reportUI.handleAction(action,id,el))return;if(extraAction(action,id))return;switch(action){
 case 'close':$('#modal').close();break;
 case 'week-prev':case 'week-next':week=addDays(week,action==='week-prev'?-7:7);day='';render();break;
 case 'week-today':week=monday(today());day='';render();break;
 case 'new-match':matchModal(id);break;
 case 'new-tournament':tournamentModal();break;
 case 'edit-tournament':tournamentModal(id);break;
 case 'new-ref':refModal();break;
 case 'assign':assignmentModal(id);break;
 case 'send':{
  if(role!=='admin')throw Error('Esta acción corresponde al administrador.');
  const selected=$(`#candidate-${slotId}`).value;
  if(!selected)throw Error('Seleccione un árbitro disponible.');
  if(el.dataset.position){
   const match=db.matches.find(m=>m.id===id);
   const position=el.dataset.position;
   if(!match||match.deletedAt||position==='Central'||!refereePositions.includes(position)||match.slots.some(s=>s.role===position))throw Error('Actualice el equipo arbitral antes de invitar.');
   const positions=refereePositions.filter(r=>r===position||match.slots.some(s=>s.role===r));
   const plan=prepareMatchUpdate(db,id,{positions,invite:{[position]:selected}},role);
   applyMatchUpdate(db,plan,role);
  }else assign(db,id,slotId,selected);
  log(`Invitación enviada a ${refName(selected)}.`);render();assignmentModal(id);toast('Invitación disponible en el perfil del árbitro.');break;
 }
 case 'cancel-invite':{const m=db.matches.find(m=>m.id===id),s=m.slots.find(s=>s.id===slotId);if(s.status!=='pending')throw Error('Esta invitación ya no está pendiente.');if(s.paid)throw Error('Revierta el pago registrado antes de retirar esta invitación.');log(`Invitación retirada para ${refName(s.ref)}: ${m.home} vs ${m.away}.`);Object.assign(s,{ref:'',status:'empty',paid:false});persist();render();assignmentModal(id);break}
 case 'accept':case 'reject':{const m=db.matches.find(m=>m.id===id);respond(db,refId,id,slotId,action==='accept'?'accepted':'rejected');log(`${refName(refId)} ${action==='accept'?'aceptó':'rechazó'}: ${m.home} vs ${m.away}.`);render();toast(action==='accept'?'Partido confirmado. Ya puede consultar la ubicación.':'Invitación rechazada. El administrador puede asignar un reemplazo.');break}
 case 'unfilled':view='matches';filter='empty';day='';query='';week=monday(today());matchPeriod='week';matchTournament='all';render();window.scrollTo({top:0});break;
 case 'as-ref':role='ref';refId=id;view='home';refTab='all';render();window.scrollTo({top:0});break;
 case 'see-availability':{const r=db.refs.find(r=>r.id===id);openModal(`Disponibilidad · ${esc(r.name)}`,`<p class="hint">${weekLabel(week)}. La disponibilidad se modifica desde el perfil del árbitro.</p>${availabilityRows(r,true)}<div class="modal-foot"><button class="btn primary" data-action="close">Cerrar</button></div>`);break}
 case 'weekend':{const form=$('#availability-form');for(let i=0;i<7;i++){const d=addDays(week,i),checked=i>=5;form.elements[`day-${d}`].checked=checked;form.elements[`start-${d}`].disabled=!checked;form.elements[`end-${d}`].disabled=!checked}toast('Fin de semana seleccionado. Guarde para aplicar.');break}
 case 'collect':{const m=db.matches.find(m=>m.id===id);if(m.deletedAt&&!m.collected)throw Error('Restaure el partido antes de registrar un cobro.');m.collected=!m.collected;log(`Cobro ${m.collected?'registrado':'revertido'}: ${m.home} vs ${m.away}.`);render();toast('Registro de cobro actualizado.');break}
 case 'confirm-payment':case 'mark-payment':case 'undo-payment':{
  const refereeConfirm=action==='confirm-payment';
  if(role!==(refereeConfirm?'ref':'admin'))throw Error('Esta acción corresponde al perfil indicado.');
  const paid=action!=='undo-payment';
  if(!recordPayment(db,id,slotId,{role,refId},paid))break;
  const match=db.matches.find(m=>m.id===id);
  const slot=match.slots.find(s=>s.id===slotId);
  const description=refereeConfirm?'confirmó que recibió el pago':paid?'tiene un pago registrado por administración':'tiene un pago revertido por administración';
  log(`${refName(slot.ref)} ${description}: ${match.home} vs ${match.away}.`);
  render();toast(refereeConfirm?'Pago recibido confirmado.':paid?'Pago registrado.':'Registro de pago revertido.');break;
 }
 case 'export':exportCSV();break;
 case 'reset':openModal('Restablecer demostración',`<p class="hint">Se borrarán los cambios guardados en este navegador y volverán los datos ficticios iniciales.</p><div class="modal-foot"><button class="btn secondary" data-action="close">Conservar cambios</button><button class="btn danger" data-action="confirm-reset">Restablecer datos</button></div>`);break;
 case 'confirm-reset':db=seed();persist();matchPeriod='all';matchTournament='all';refScope='all';financeState='all';refTab='all';refPaymentState='all';calendarMonth=today().slice(0,7);calendarDate=today();calendarType='all';role='admin';view='overview';week=monday(today());day='';filter='all';query='';tournamentFilter='all';$('#modal').close();render();toast('Demostración restablecida.');break;
 }}catch(error){if($('#modal').open&&$('#modal-error'))$('#modal-error').textContent=error.message;else toast(error.message)}
});
document.addEventListener('input',e=>{if(e.target.id==='search'){query=e.target.value;$('#match-list').innerHTML=matchList()}});
document.addEventListener('change',e=>{
 if(e.target.id==='role'){role=e.target.value==='admin'?'admin':'ref';if(role==='ref')refId=e.target.value;view=role==='admin'?'overview':'home';day='';query='';refTab='all';refPaymentState='all';week=monday(today());render()}
 const matchForm=e.target.closest('#match-form, #match-edit-form[data-mode="edit"]');
 if(matchForm&&(e.target.name==='tournament'||e.target.hasAttribute('data-team-position'))){
  updateTeamFields(matchForm,e.target.name==='tournament');
 }
 if(e.target.id==='match-period'){matchPeriod=e.target.value;week=monday(today());render()}
 if(e.target.id==='match-tournament'){matchTournament=e.target.value;render()}
 if(e.target.id==='ref-scope'){refScope=e.target.value;render()}
 if(e.target.id==='finance-state'){financeState=e.target.value;render()}
 if(e.target.id==='ref-payment-state'){refPaymentState=e.target.value;render()}
 if(e.target.id==='finance-filter'){tournamentFilter=e.target.value;render()}
 if(e.target.dataset.availability){const date=e.target.dataset.availability;const form=e.target.closest('form');if(form){form.elements[`start-${date}`].disabled=!e.target.checked;form.elements[`end-${date}`].disabled=!e.target.checked}}
});
document.addEventListener('submit',e=>{
 const form=e.target;e.preventDefault();if(!form.reportValidity())return;const f=new FormData(form),get=k=>String(f.get(k)||'').trim(),num=k=>Number(get(k));
 try{
 if(reportUI.handleSubmit(form,f,e.submitter))return;
 if(form.id==='match-edit-form'){
  if(role!=='admin')throw Error('Esta acción corresponde al administrador.');
  const patch={date:get('date'),time:get('time'),duration:num('duration'),venue:get('venue'),lat:get('lat')===''?null:num('lat'),lng:get('lng')===''?null:num('lng'),reason:get('reason')};
  if(form.dataset.mode!=='reschedule'){
   Object.assign(patch,{tournament:get('tournament'),home:get('home'),away:get('away'),charge:num('charge')},chosenTeam(f));
  }
  const plan=prepareMatchUpdate(db,form.dataset.id,patch,role,{reschedule:form.dataset.mode==='reschedule'});
  if(plan.noop){$('#modal').close();toast('No hubo cambios en el partido.');return;}
  plan.teamSelection=patch.teamSelection;
  plan.returnView=form.dataset.origin;matchReview(plan);
 }else if(form.id==='delete-match-form'){
  const m=deleteMatch(db,form.dataset.id,get('reason'),role);pendingMatchPlan=null;log(`Partido eliminado: ${m.home} vs ${m.away}.`);$('#modal').close();render();toast('Partido movido a Eliminados. Puede restaurarlo desde Partidos.');
 }else if(form.id==='event-form'){
  const old=db.calendarEvents.find(e=>e.id===form.dataset.id);
  const item={id:old?.id||uid(),title:get('title'),category:get('category'),date:get('date'),time:get('time'),duration:num('duration'),venue:get('venue'),notes:get('notes'),reminderDays:get('reminder')==='none'?null:num('reminder'),reminderSeen:false,status:get('status')||'scheduled',sequence:old?(old.sequence||0)+1:0};
  validateCalendarEvent(item);if(old)Object.assign(old,item);else db.calendarEvents.push(item);
  log(`Evento ${old?'actualizado':'creado'}: ${item.title}.`);calendarDate=item.date;calendarMonth=item.date.slice(0,7);calendarType='all';view='calendar';$('#modal').close();render();toast('Evento guardado en el calendario.');
 }else if(form.id==='match-form'){
  if(role!=='admin')throw Error('Esta acción corresponde al administrador.');
  const {positions,fees,invite}=chosenTeam(f);
  const m={id:uid(),tournament:get('tournament'),home:get('home'),away:get('away'),date:get('date'),time:get('time'),duration:num('duration'),venue:get('venue'),lat:get('lat')===''?null:num('lat'),lng:get('lng')===''?null:num('lng'),charge:num('charge'),collected:false,slots:positions.map(position=>openPosition(position,fees[position]))};
  validateMatch(db,m);
  const context={...db,matches:[...db.matches,m]};
  for(const slot of m.slots){
   if(invite[slot.role])assign(context,m.id,slot.id,invite[slot.role]);
  }
  db.matches.push(m);matchPeriod='all';matchTournament='all';week=monday(m.date);day='';filter='all';query='';view='matches';
  log(`Partido creado: ${m.home} vs ${m.away}.`);$('#modal').close();render();
  toast(Object.keys(invite).length?'Partido creado e invitaciones registradas.':'Partido creado. Ya puede asignar árbitros.');
 }else if(form.id==='tournament-form'){
  const refs=f.getAll('refs'),name=get('name'),reportEmail=get('reportEmail');if(reportEmail&&!validReportEmail(reportEmail))throw Error('Ingrese un correo válido para recibir los informes.');if(!name||!get('organizer')||!get('category'))throw Error('Complete los datos del torneo.');if(!refs.length)throw Error('Seleccione al menos un árbitro para el panel.');
  const id=form.dataset.id,t=db.tournaments.find(t=>t.id===id);
  if(t){const assigned=liveMatches(db).filter(m=>m.tournament===id).flatMap(m=>m.slots).filter(active).map(s=>s.ref);if(assigned.some(r=>!refs.includes(r)))throw Error('Conserve en el panel a los árbitros con invitaciones o nombramientos activos.');Object.assign(t,{name,organizer:get('organizer'),category:get('category'),reportEmail,refs})}else db.tournaments.push({id:uid(),name,organizer:get('organizer'),category:get('category'),reportEmail,refs});
  log(`Torneo ${t?'actualizado':'creado'}: ${name}.`);$('#modal').close();render();toast('Torneo guardado.');
 }else if(form.id==='ref-form'){
  if(!get('name'))throw Error('Ingrese el nombre del árbitro.');if(db.refs.some(r=>r.email.toLowerCase()===get('email').toLowerCase()))throw Error('Este correo ya está registrado.');
  db.refs.push({id:uid(),name:get('name'),email:get('email'),level:get('level'),availability:{}});log(`Árbitro agregado: ${get('name')}.`);$('#modal').close();render();toast('Árbitro agregado. Asígnele torneos y registre su disponibilidad desde su perfil.');
 }else if(form.id==='availability-form'){
  const next={};for(let i=0;i<7;i++){const d=addDays(week,i);if(f.has(`day-${d}`)){const start=get(`start-${d}`),end=get(`end-${d}`);if(!start||!end||start>=end)throw Error(`Revise el horario del ${dateLabel(d)}: la hora final debe ser posterior a la inicial.`);next[d]={start,end}}}
  const r=db.refs.find(r=>r.id===refId);for(let i=0;i<7;i++)delete r.availability[addDays(week,i)];Object.assign(r.availability,next);log(`Disponibilidad actualizada: ${r.name}.`);render();toast('Disponibilidad semanal guardada.');
 }
 }catch(error){const target=form.id==='availability-form'?$('#availability-error'):$('#modal-error');if(target)target.textContent=error.message;else toast(error.message)}
});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const rect=$('#modal').getBoundingClientRect();if(e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom)$('#modal').close()}});
persist();render();
let reminderClockKey=dueReminders(db.calendarEvents).map(e=>e.id).join('|');
function refreshReminders(){
 const next=dueReminders(db.calendarEvents).map(e=>e.id).join('|');
 if(next!==reminderClockKey&&!document.hidden&&!$('#modal').open&&role==='admin'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName)){
  reminderClockKey=next;render();
 }
}
window.setInterval(refreshReminders,60000);
document.addEventListener('visibilitychange',refreshReminders);

